from pathlib import Path
p=Path('playtest/index.html')
s=p.read_text()
s=s.replace('0.19.5-r7-storypass','0.20.0-narrative-flow').replace("version:'0.19.5-r7'","version:'0.20.0'").replace("BUILD_SCHEMA='0195-r7'","BUILD_SCHEMA='0200'")
intro=r'''<script id="v020-chapter1-intro">(()=>{const K='eldoria-v020-ch1-intro';function fresh(){const t=document.body.innerText;return /CAPÍTULO I|Las Cenizas de Valoria|Granero/i.test(t)&&!/CAPÍTULO II/i.test(t)}function start(){if(!fresh()||localStorage.getItem(K)||document.querySelector('.aldric-cinematic'))return;localStorage.setItem(K,'1');const full='Mi señor, Valoria sobrevivió… pero apenas.\n\nNuestros almacenes están vacíos, los talleres destruidos y los soldados dispersos. Antes de buscar respuestas sobre la Brecha, debemos conseguir que el reino vuelva a sostenerse.\n\nEmpecemos por el Granero. Sin alimento, Valoria no puede levantarse.';const o=document.createElement('div');o.className='aldric-cinematic';o.dataset.scene='chapter1-intro-v020';o.innerHTML='<div class="aldric-dialogue"><div class="aldric-head"><div class="aldric-portrait">⚔</div><div><div class="aldric-name">SIR ALDRIC</div><div class="aldric-role">Guardián de Valoria</div></div></div><div class="aldric-copy"><div class="aldric-ghost"></div><div class="aldric-typed"></div></div><div class="aldric-wait">ESCUCHA…</div><button class="aldric-continue primary" type="button">Continuar</button></div>';document.body.appendChild(o);document.documentElement.style.overflow='hidden';const b=o.querySelector('.aldric-dialogue'),g=o.querySelector('.aldric-ghost'),t=o.querySelector('.aldric-typed'),btn=o.querySelector('button');g.textContent=full;let i=0;(function type(){if(i<full.length){t.textContent=full.slice(0,++i);setTimeout(type,22)}else{b.classList.add('done')}})();btn.onclick=()=>{if(!b.classList.contains('done'))return;o.remove();document.documentElement.style.overflow='';[...document.querySelectorAll('button,[role=button],.building')].find(e=>/granero/i.test(e.innerText||e.textContent||''))?.classList.add('v020-focus')}}setTimeout(start,500);new MutationObserver(()=>setTimeout(start,80)).observe(document.documentElement,{subtree:true,childList:true})})();</script>'''
if 'v020-chapter1-intro' not in s:s=s.replace('</body>',intro+'</body>')
p.write_text(s)
print('Restored validated v0.20 narrative layer')
